std::vector<std::string> splitByTab(const std::string& line) {
	std::vector<std::string> tokens;
	std::stringstream ss(line);
	std::string item;

	// Extract substrings separated by tab
	while (std::getline(ss, item, '\t')) {
		tokens.push_back(item);
	}

	return tokens;
}



